CREATE TABLE DATA.t_cats_transport_cost_1 (
client_id 					NUMBER(38,0) 	NOT NULL 	COMMENT 'Client id - calculated based on the country_1 code', 
country_cd					VARCHAR(5)  	NULL 		COMMENT 'Country_1 code (two digits). Original name: Country_1',
rdc                         VARCHAR(512) 	NULL 		COMMENT 'Company name',
rdc_id                      VARCHAR(5)  	NULL 		COMMENT 'Company code (three digits)',
rdc_id_nr                   VARCHAR(10) 	NULL 		COMMENT 'Company number consisting of two-digit country_1 code and four-digit company number (total of six digits)',
carrier_name                VARCHAR(512) 	NULL 		COMMENT 'Full carrier name',
carrier_id                  VARCHAR(512) 	NULL 		COMMENT 'Unique forwarding ID; corresponds to the Business Partner ID from SAP',
delivery_dt                 DATE 			NULL 		COMMENT 'Delivery day of the tour. Original name: Date',
cw                          NUMBER(38,0) 	NULL 		COMMENT 'Calendar_1 week of the tour_1',
resource_set_id             VARCHAR(512) 	NULL 		COMMENT 'Individual ID of the resource set from Quintiq',
shift                       NUMBER(38,0) 	NULL 		COMMENT 'Specification in the number of shifts of a day of a resource set the tour_1 takes place (single digit)',
tour_id                     VARCHAR(512) 	NULL 		COMMENT 'Tour_1 number (unique per day and company, multiple digits)',
licence_plate               VARCHAR(512) 	NULL 		COMMENT 'License plate of the truck or tractor unit_1 with which the tour_1 was carried out',
shift_indicator             VARCHAR(512) 	NULL 		COMMENT 'Shift indicator of the tour_1 (use dependent on regional distribution center and setting in Quintiq)',
means_of_transport          VARCHAR(512) 	NULL 		COMMENT 'Transport resource with which the tour_1 was carried out (INT definition of individual vehicle resources, data from Quintiq) (e.g. tractor or trailer)',
unique_tour_id              VARCHAR(512) 	NULL 		COMMENT 'Unique ID for each tour_1 within a country_1; Combination of delivery date and tour_1 ID (YYMMDDTourID). Original name: UID',
stores                      VARCHAR(512) 	NULL 		COMMENT 'Store numbers or numbers of the special addresses that are approached with the route separated by - in the order of approach',
resource_type               VARCHAR(512) 	NULL 		COMMENT 'Vehicle type with which the tour_1 is carried out (e.g. articulated truck) (data from Quintiq)',
resource_technique          VARCHAR(512) 	NULL 		COMMENT 'Vehicle technology with which the tour_1 is carried out (e.g. mono- / bi-temp) (data from Quintiq)',
fuel_type                   VARCHAR(512) 	NULL 		COMMENT 'Type of drive with which the tour_1 was carried out (data from Quintiq)',
total_tour_km               FLOAT		 	NULL 		COMMENT 'Total number of kilometers of the tour. Original name: KM',
toll_km                     FLOAT		 	NULL 		COMMENT 'Total number of kilometers subject to tolls for the route (use depends on country_1 configuration)',
total_pallets               FLOAT		 	NULL 		COMMENT 'Total number of pallet spaces loaded on route (accurate to 0.5)',
duration                    FLOAT		 	NULL 		COMMENT 'Total duration of the tour_1 in hours',
cost_indicator              VARCHAR(512) 	NULL 		COMMENT 'Predefined comments per tour_1 (can store country_1 in Quintiq)',
cost_indicator_amount       VARCHAR(512) 	NULL 		COMMENT 'Numerical value (country_1-specific definition from Quintiq)',
comment_txt                 VARCHAR(2048) 	NULL 		COMMENT 'Free comment field of the tour_1 from Quintiq. Original name: Comment',
fix_costs                   FLOAT		 	NULL 		COMMENT 'Fixed costs associated with the tour_1 in local currency',
variable_costs              FLOAT		 	NULL 		COMMENT 'Variable costs associated with the tour_1 in local currency',
floater                     FLOAT		 	NULL 		COMMENT 'Fuel floater costs in local currency associated with the tour_1',
surcharges                  FLOAT		 	NULL 		COMMENT 'Tour_1 surcharges in local currency',
additional_services         FLOAT		 	NULL 		COMMENT 'Additional costs for the tour_1 in local currency',
toll                        FLOAT		 	NULL 		COMMENT 'Toll costs for the tour_1 in local currency',
other_costs                 FLOAT		 	NULL 		COMMENT 'Other costs of the tour_1 in local currency',
invoice_matching            VARCHAR(512) 	NULL 		COMMENT 'Negative total invoice amount',
total                       FLOAT		 	NULL 		COMMENT 'Total costs of the tour_1 in local currency',
hotrun                      VARCHAR(512) 	NULL 		COMMENT 'Has the event that is associated with the tour_1 in CATS, the status_1 Hotrun and thus ended the process in CATS (states Y and N)',
invoice_status              VARCHAR(512) 	NULL 		COMMENT 'Status_1 of invoice processing',
invoice_number              VARCHAR(512) 	NULL 		COMMENT 'Unique number of the billing document created in CnB for each country. Before Hotrun: RDC-Abbreviation_Carrier Abbreviation_KW_Year_Number_Rechnungsnummer. After Hotrun: six-digit counter / year number',
external_invoice_number     VARCHAR(2048) 	NULL 		COMMENT 'Unique invoice number for each country_1',
currency                    VARCHAR(512) 	NULL 		COMMENT 'National currency, stored for each freight forwarder',
total_consumption           FLOAT		 	NULL 		COMMENT 'Fuel consumption of the tour_1',
reference_price             FLOAT		 	NULL 		COMMENT 'Reference price of the fuel floater calculation in local currency associated with the tour_1',
calculated_fuel_costs       FLOAT		 	NULL 		COMMENT 'Total fuel costs associated with the tour_1',
total_excl_fuel_costs       FLOAT		 	NULL 		COMMENT 'Total cost of the tour_1 excluding fuel costs',
pallets_1a                  FLOAT		 	NULL 		COMMENT 'Number of 1a pallets on the route (accurate to 0.5). Original name: 1A Pallets',
xwh_pallets_1b              FLOAT		 	NULL 		COMMENT 'Number of 1b external warehouse pallets on the route (accurate to 0.5). Original name: 1B XWH Pallets',
rdc_pallets_1b              FLOAT		 	NULL 		COMMENT 'Number of 1b redistribution pallets on the route (accurate to 0.5). Original name: 1B RDC Pallets',
nf_pallets_1b               FLOAT		 	NULL 		COMMENT 'Number of 1b non-food pallets on the route (accurate to 0.5). Original name: 1B NF Pallets',
total_standard_costs        FLOAT		 	NULL 		COMMENT 'Total standard costs of the tour_1 in local currency',
costs_1a                    FLOAT		 	NULL 		COMMENT '1A standard costs in local currency (part of Total Standard Costs). Original name: 1A Costs',
xwh_costs_1b                FLOAT		 	NULL 		COMMENT '1b- External warehouse standard costs in local currency (part of Total Standard Costs). Original name: 1B XWH Costs',
rdc_costs_1b                FLOAT		 	NULL 		COMMENT '1b standard stock transfer costs in local currency (part of Total Standard Costs). Original name: 1B RDC Costs',
nf_costs_1b                 FLOAT		 	NULL 		COMMENT '1b non-food costs (part of total standard costs). Original name: 1B NF Costs',
total_toll_costs            FLOAT		 	NULL 		COMMENT 'Total toll costs for the tour_1 in local currency',
toll_costs_1a               FLOAT		 	NULL 		COMMENT '1A share of total toll costs in local currency. Original name: 1A Toll Costs',
xwh_toll_costs_1b           FLOAT		 	NULL 		COMMENT 'Share of 1B external warehouse in total toll costs in local currency. Original name: 1B XWH Toll Costs',
rdc_toll_costs_1b           FLOAT		 	NULL 		COMMENT 'Share of 1B regional stock transfer of total toll costs in local currency. Original name: 1B RDC Toll Costs',
nf_toll_costs_1b            FLOAT		 	NULL 		COMMENT 'Share of 1b non-food in total toll costs in local currency. Original name: 1B NF Toll Costs',
other_costs2                FLOAT		 	NULL 		COMMENT 'Other costs in local currency. Original name: Other Costs',
fix_costs_shift             FLOAT		 	NULL 		COMMENT 'Fixed shift costs in local currency associated with tour_1',
fix_costs_oneway            FLOAT		 	NULL 		COMMENT 'Fixed one-way costs in local currency associated with the tour_1',
fix_costs_day               FLOAT		 	NULL 		COMMENT 'Fixed daily costs in local currency associated with the tour_1',
fix_costs_tour              FLOAT		 	NULL 		COMMENT 'Fixed tour_1 costs in local currency associated with tour_1',
fix_costs_predefined_tour   FLOAT		 	NULL 		COMMENT 'Fixed, predefined tour_1 costs in local currency associated with tour_1',
variable_costs_km           FLOAT		 	NULL 		COMMENT 'Variable costs per km associated with the tour_1 in local currency',
variable_costs_hour         FLOAT		 	NULL 		COMMENT 'Cost per hour associated with the tour_1 in local currency',
variable_costs_stop         FLOAT		 	NULL 		COMMENT 'Variable costs per stop in local currency',
surcharge_sunday            FLOAT		 	NULL 		COMMENT 'Sunday surcharge in local currency associated with the tour_1',
surcharge_tail_lift         FLOAT		 	NULL 		COMMENT 'Lifting platform surcharge in local currency associated with tour_1',
surcharge_frozen_goods      FLOAT		 	NULL 		COMMENT 'Frozen surcharge in local currency associated with tour_1',
fuel_floater_km             FLOAT		 	NULL 		COMMENT 'Number of kilometers used for the fuel floater calculation',
toll_costs_quintiq          FLOAT		 	NULL 		COMMENT 'Toll costs transferred from Quintiq in local currency',
placeholder_14              VARCHAR(512) 	NULL 		COMMENT 'Free columns for country_1-specific use. Original name: 14',
placeholder_15              VARCHAR(512) 	NULL 		COMMENT 'Free columns for country_1-specific use. Original name: 15',
carrier_day_id              VARCHAR(512) 	NULL 		COMMENT 'Combination of columns RDC ID NR _ Carrier ID _ Date (format YYMMDD)',
carrier_resourceset_id      VARCHAR(512) 	NULL 		COMMENT 'Combination of columns RDC ID _ Carrier ID _ Date (format YYMMDD) _ Resource Set ID',
carrier_shift_id            VARCHAR(512) 	NULL 		COMMENT 'Combination of columns RDC ID _ Carrier ID _ Date (format YYMMDD) _ Resource Set ID _ Preceding S directly followed by the contents of the Shift column',
carrier_tour_id             VARCHAR(512) 	NOT NULL 	COMMENT 'Combination of columns RDC ID _ Carrier ID _ Date (format YYMMDD) _ Resource Set ID _ Leading S directly followed by contents of the Shift column _ Leading T followed by contents of the Tour_1 ID column',
dwh_load_id    				NUMBER(38,0) 	NOT NULL 	COMMENT 'Load id',
dwh_created    				TIMESTAMP 		NOT NULL 	COMMENT 'Record created at',
dwh_updated    				TIMESTAMP 		NOT NULL 	COMMENT 'Record updated at',
PRIMARY KEY (client_id,carrier_tour_id)
) COMMENT = 'CATS - an overview of the transport costs.';